-- 115: Original BrillaPrep WASSCE Agricultural Science beta questions, part 2.
-- Curriculum-aligned practice content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_011', 'topic_was_agric_1_3', 'subj_wassce_agric', 'exam_wassce', 'What is the safest action before clearing material wrapped around a tractor power take-off shaft?', 'multiple_choice', '["A. Pull the material while the shaft rotates slowly","B. Step over the rotating shaft","C. Shut down the engine, isolate power and wait for all movement to stop","D. Increase engine speed to throw it off"]', 'C', 'A rotating power take-off can entangle clothing or limbs within seconds. Isolation and complete stoppage are essential before inspection or clearing. Therefore the correct answer is C: Shut down the engine, isolate power and wait for all movement to stop.', 'medium', 1, 1, 90, 'st_was_agric_1_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_012', 'topic_was_agric_1_3', 'subj_wassce_agric', 'exam_wassce', 'Which maintenance practice most directly reduces rapid wear of moving machine parts?', 'multiple_choice', '["A. Leaving soil on metal surfaces after use","B. Operating with loose fasteners","C. Replacing clean oil with water","D. Lubricating specified points at the recommended intervals"]', 'D', 'Correct lubrication reduces friction and heat between moving surfaces. The manufacturer’s schedule and lubricant specification should be followed for reliable operation. Therefore the correct answer is D: Lubricating specified points at the recommended intervals.', 'hard', 2, 2, 90, 'st_was_agric_1_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_013', 'topic_was_agric_2_1', 'subj_wassce_agric', 'exam_wassce', 'Why is crop rotation with a legume useful in a cereal production plan?', 'multiple_choice', '["A. It can improve soil nitrogen supply and interrupt some pest cycles","B. It guarantees that weeds disappear permanently","C. It removes the need for all soil testing","D. It makes rainfall unnecessary"]', 'A', 'Legumes can add biologically fixed nitrogen when residues are managed well. Changing crop families can also disrupt organisms that depend on one host crop. Therefore the correct answer is A: It can improve soil nitrogen supply and interrupt some pest cycles.', 'easy', 1, 1, 90, 'st_was_agric_2_1', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_014', 'topic_was_agric_2_1', 'subj_wassce_agric', 'exam_wassce', 'What is the first principle of integrated pest management?', 'multiple_choice', '["A. Apply the highest pesticide dose every week","B. Monitor the crop and combine suitable controls only when justified","C. Destroy all organisms found in the field","D. Ignore economic damage thresholds"]', 'B', 'Integrated pest management uses identification, monitoring, prevention and compatible biological, cultural or chemical controls. Treatment is based on evidence and risk. Therefore the correct answer is B: Monitor the crop and combine suitable controls only when justified.', 'medium', 2, 2, 90, 'st_was_agric_2_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_015', 'topic_was_agric_2_1', 'subj_wassce_agric', 'exam_wassce', 'A vegetable farmer harvests produce during the coolest part of the morning. What benefit is most likely?', 'multiple_choice', '["A. The produce immediately becomes sterile","B. Respiration stops permanently","C. Lower field heat can slow water loss and quality deterioration","D. Every bruise repairs itself"]', 'C', 'Removing field heat and limiting dehydration help preserve fresh produce. Careful handling, shade and timely cooling further reduce post-harvest losses. Therefore the correct answer is C: Lower field heat can slow water loss and quality deterioration.', 'hard', 3, 3, 90, 'st_was_agric_2_1', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_016', 'topic_was_agric_2_1', 'subj_wassce_agric', 'exam_wassce', 'Which calculation gives gross margin for a crop enterprise?', 'multiple_choice', '["A. Total assets minus rainfall","B. Fixed costs plus every household expense","C. Yield divided by the farmer’s age","D. Revenue minus variable costs"]', 'D', 'Gross margin compares enterprise income with costs that change with production, such as seed, fertiliser and hired labour. It supports comparison between enterprise options. Therefore the correct answer is D: Revenue minus variable costs.', 'easy', 2, 2, 90, 'st_was_agric_2_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_017', 'topic_was_agric_2_2', 'subj_wassce_agric', 'exam_wassce', 'Why should newly purchased animals be quarantined before joining an established flock?', 'multiple_choice', '["A. To observe them and reduce the chance of introducing disease","B. To prevent them from eating forever","C. To make vaccination unnecessary","D. To increase stocking density immediately"]', 'A', 'Quarantine separates new animals while health checks and required treatments are completed. This lowers the risk of spreading an undetected infection to the resident flock. Therefore the correct answer is A: To observe them and reduce the chance of introducing disease.', 'medium', 1, 1, 90, 'st_was_agric_2_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_018', 'topic_was_agric_2_2', 'subj_wassce_agric', 'exam_wassce', 'What makes an animal ration balanced?', 'multiple_choice', '["A. It contains only the cheapest ingredient","B. It supplies required nutrients in suitable amounts and proportions","C. It provides protein but no water","D. It is identical for every species and age"]', 'B', 'A balanced ration matches energy, protein, minerals, vitamins, fibre and water needs to the animal’s species, age, production stage and health. Therefore the correct answer is B: It supplies required nutrients in suitable amounts and proportions.', 'hard', 2, 2, 90, 'st_was_agric_2_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_019', 'topic_was_agric_2_2', 'subj_wassce_agric', 'exam_wassce', 'Why must a farmer record vaccination dates and batch details?', 'multiple_choice', '["A. To prove that no animal can ever become ill","B. To replace correct vaccine storage","C. To schedule protection, trace products and investigate health events","D. To avoid observing withdrawal instructions"]', 'C', 'Accurate health records support timely boosters and traceability. They also help a veterinarian assess failures, reactions and compliance with product directions. Therefore the correct answer is C: To schedule protection, trace products and investigate health events.', 'easy', 1, 1, 90, 'st_was_agric_2_2', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_020', 'topic_was_agric_2_2', 'subj_wassce_agric', 'exam_wassce', 'In a fish pond, dissolved oxygen falls sharply before dawn. Which response is most appropriate?', 'multiple_choice', '["A. Add more feed immediately","B. Block all water movement","C. Cover the pond completely with an airtight sheet","D. Increase aeration and check stocking and feeding levels"]', 'D', 'Respiration continues overnight while photosynthesis stops, so oxygen can reach its daily minimum near dawn. Aeration addresses the immediate risk while management causes are reviewed. Therefore the correct answer is D: Increase aeration and check stocking and feeding levels.', 'medium', 3, 3, 90, 'st_was_agric_2_2', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-agric-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Agricultural Science curriculum; not official WAEC or NaCCA examination material.', 'https://nacca.gov.gh/wp-content/uploads/2025/04/Agricultural-Science-Curriculum.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_agric_b001_011' AND 'q_was_agric_b001_020';
